<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Mini Spreadsheet</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            font-family: Arial, sans-serif;
        }

        canvas {
            width: 600px;
            height: 400px;
            display: block;
        }

        #cell-A1 { position: absolute; top: -50px; left: 10%; }
        #cell-B2 { position: absolute; top: 0; left: 10%; }
    </style>
</head>
<body>
    <canvas id="myCanvas"></canvas>

    <script>
        // Grid setup with formulas array
        let formulas = Array.from({ length: 100 }, () => []);

        // Function to evaluate a formula safely (basic arithmetic evaluation)
        function evaluateFormula(formula) {
            try {
                // Replace '=' with &amp; to avoid issues in eval
                const safeFormula = formula.replace(/=/g, '&amp;');
                // Evaluate using new environment for safety
                let result = eval(safeFormula);
                return Number(result);
            } catch (error) {
                return "ERR";
            }
        }

        // Function to write CSV
        function writeCsv() {
            let csvRows = [];
            formulas.forEach(row => {
                row.forEach(cell => {
                    const formulaStr = cell.replace(/=/g, '&amp;');
                    const computedValue = evaluateFormula(formulaStr) || 0;
                    csvRows.push({ [cell]: computedValue });
                });
            });
            document.getElementById('csv').value += '\n'.join(
                csvRows.map(row => row[cell] + "\t")
            );
        }

        // Function to render cell (for initial display)
        function renderCell(id, value) {
            const cell = document.createElement(`div`);
            if (id.startsWith('cell-')) {
                id = id.slice(7); // remove leading "cell-"
            }
            cell.textContent = value;
            return cell; // for inline form
        }

        // Initialize grid cells with formulas
        formulas.forEach(row => row.forEach(cell => {
            document.getElementById(`cell-${row[1] + 8}`).innerHTML = `=${cell}&&`;
            cell.style.backgroundColor = "#f0f0f0";
        }));

        // Event listeners for editing and recalculations
        window.onload = () => {
            document.getElementById('export').addEventListener('click', writeCsv);

            const cells = Array.from({ length: 100 }, (_, i) => `cell-${i + 1}&&`);
            cells.forEach(cellId => {
                const cellElement = document.createElement(`div class="cell ${cellId}" style="display:none;"></div>`);
                // For simplicity, we'll simulate recalculations
                // In a real implementation, formulas would be stored in a more complex structure
                // and cell data would be maintained across cells.
            });
        };
    </script>
</body>
</html>
